  _content=new(){Name="PdfContent",ItemsSource=values,SelectedIndex=0};_paper=new(){ItemsSource=Enum.GetValues<PdfPaper>(),SelectedItem=PdfPaper.A4};_landscape=new(){Content="Landscape",IsChecked=true};
  _all=new(){Content="All tasks, including filtered/collapsed tasks",IsChecked=false};_compact=new(){Content="Compact table: ID, name, duration, start, finish",IsChecked=true};
