  Field("Content",_content);Field("Paper",_paper);Field("Orientation",_landscape);Field("Rows per page",_rows,"More rows reduce text size; every row is exported, including rows outside the screen.");Field("Fit to pages wide",_wide,"1 fits the timescale to one page width. More pages add horizontal detail; table headers repeat.");Field("Task selection",_all,"By default, export current table rows in the current display order. Timelines export their pinned tasks.");Field("Table columns",_compact,"Uncheck to export the current visible columns. Many columns may need larger paper for readable text.");Field("Chart details",new StackPanel{Children={_legend,_links,_baseline}});Field("Date limits",_dates,"Uses the current Gantt limits, or each timeline's own limits, unless overridden.");Field("Start",_start);Field("Finish (inclusive)",_finish);
  _margin=new(){Name="PdfMargins",Minimum=5,Maximum=40,Value=12.7m,Increment=1};_fitTall=new(){Name="PdfFitTall",Content="Fit all task rows to one page tall",IsChecked=false};_header=new(){Name="PdfHeader",Text=projectName,Watermark="Project name"};_footer=new(){Name="PdfFooter",Text=projectName,Watermark="Project name"};Field("Margins (mm)",_margin,"Applied to every edge of the page.");Field("Scaling",_fitTall,"For long plans, paginated rows are easier to read. Fit to one page can make text small.");Field("Header",_header);Field("Footer",_footer,"Page numbers are added automatically.");
  var groups=Fields.Children.ToArray();Fields.Children.Clear();Control Section(params int[] indices){var panel=new StackPanel{Spacing=12,Margin=new Avalonia.Thickness(0,12)};foreach(int i in indices)panel.Children.Add(groups[i]);return new ScrollViewer{Content=panel};}var tabs=new TabControl{Name="PdfPageSetupTabs",Height=570,Items={new TabItem{Header="View",Content=Section(0,5,6,7)},new TabItem{Header="Page",Content=Section(1,2,4,3,11,12)},new TabItem{Header="Dates",Content=Section(8,9,10)},new TabItem{Header="Header / Footer",Content=Section(13,14)}}};Fields.Children.Add(tabs);
  void Update(){bool timeline=(_content.SelectedItem as FormatChoice)?.Value==PdfContent.Timelines;_all.IsEnabled=!timeline;_compact.IsEnabled=(_content.SelectedItem as FormatChoice)?.Value==PdfContent.TableAndGantt;_start.IsEnabled=_finish.IsEnabled=_dates.IsChecked==true;_fitTall.IsEnabled=!timeline;_rows.IsEnabled=timeline||_fitTall.IsChecked!=true;}_content.SelectionChanged+=(_,_)=>Update();_dates.IsCheckedChanged+=(_,_)=>Update();_fitTall.IsCheckedChanged+=(_,_)=>Update();Update();
  if(preview!=null){var apply=this.GetLogicalDescendants().OfType<Button>().Single(b=>Equals(b.Content,"Apply"));var actions=(StackPanel)apply.Parent!;var button=new Button{Content="Preview…"};button.Click+=async(_,_)=>{button.IsEnabled=false;try{var images=await preview(Read());await new PdfPreviewWindow(images).ShowDialog(this);}catch(Exception e){Error.Text=e.Message;}finally{button.IsEnabled=true;}};actions.Children.Insert(0,button);}
